    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    M = int(data[1])
    A = [int(x) - 1 for x in data[2:2+N]]

    on_cycle = [False] * N
    visited = [False] * N
    cycles = []

    for start in range(N):
        if visited[start]:
            continue
