            cycle = path[idx[u]:]
            cycles.append(cycle)
            for c in cycle:
                on_cycle[c] = True
        for p in path:
            visited[p] = True

    children_of = [[] for _ in range(N)]
    for i in range(N):
        children_of[A[i]].append(i)

    f = [None] * N
    order = []
