        fu = [0] * (M + 1)
        s = 0
        for v in range(1, M + 1):
            s = (s + g[v]) % MOD
            fu[v] = s
        f[u] = fu

    answer = 1
    for cycle in cycles:
        prod_per_v = [1] * (M + 1)
        for c in cycle:
            for t in children_of[c]:
