                    continue
                ft = f[t]
                for v in range(1, M + 1):
                    prod_per_v[v] = prod_per_v[v] * ft[v] % MOD
        total = 0
        for v in range(1, M + 1):
            total = (total + prod_per_v[v]) % MOD
